values ('ap_biology', 3, '3.5', array['3.5']::text[], 'list_sequence', 'Aerobic cellular respiration in eukaryotes: order of stages', 'Order in which aerobic respiration captures energy from glucose in a eukaryotic cell, from glycolysis through oxidative phosphorylation.', '[{"label": "1. Glycolysis (cytosol)", "meaning": "Releases energy in glucose to form ATP, NADH (from NAD+), and pyruvate"}, {"label": "2. Pyruvate transport and oxidation", "meaning": "Pyruvate moves from the cytosol to the mitochondrion, where oxidation occurs"}, {"label": "3. Krebs (citric acid) cycle (mitochondrial matrix)", "meaning": "Releases CO2, synthesizes ATP, and reduces NAD+ to NADH and FAD to FADH2"}, {"label": "4. Electron transport chain (inner mitochondrial membrane)", "meaning": "NADH and FADH2 deliver electrons that pass through the ETC to oxygen, the terminal electron acceptor, and a proton gradient forms"}, {"label": "5. Oxidative phosphorylation", "meaning": "Protons flow back through ATP synthase by chemiosmosis, driving ATP formation from ADP and inorganic phosphate"}]'::jsonb, NULL, NULL, 'published', 'generated-checked; extractor=anthropic/claude-sonnet-5.5; batch=ap-biology-reference-u1-u3-2026-10-10; candidate=ap_biology-u3-r2-004; ced=3.5.B.1–3.5.B.5, 3.5.A.3 — "Electrons extracted in glycolysis and Krebs cycle reactions are transferred by NADH and FADH2 to the ETC"')
